"use server";

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import bcrypt from "bcryptjs";
import type { Role } from "@prisma/client";
import { db } from "./db";
import { requireAdmin } from "./auth";
import { normalizeEmail } from "./email-normalize";
import { normalizeCidr } from "./firewall-rules";
import { GRANTABLE_AREAS } from "./staff-grants";
import type { Area } from "./rbac";

const roleSchema = z.enum(["CUSTOMER", "SUPPORT", "BILLING", "ADMIN"]);

/**
 * Promote/demote a user's role. ADMIN-only, audit-logged. An admin can't
 * change their own role (prevents locking yourself out of admin).
 */
export async function setUserRole(
  userId: string,
  role: Role,
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();

  const parsed = roleSchema.safeParse(role);
  if (!parsed.success) return { error: "Invalid role." };

  if (userId === admin.id) return { error: "You can't change your own role." };

  const target = await db.user.findUnique({ where: { id: userId } });
  if (!target) return { error: "User not found." };
  if (target.role === parsed.data) return { ok: true };

  await db.user.update({ where: { id: userId }, data: { role: parsed.data } });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "staff.setRole",
      detail: `${target.email}: ${target.role} → ${parsed.data}`,
    },
  });

  revalidatePath("/admin/staff");
  revalidatePath(`/admin/users/${userId}`);
  return { ok: true };
}

function isGrantableArea(area: unknown): area is Area {
  return GRANTABLE_AREAS.some((g) => g.area === area);
}

/**
 * Create a Role.EMPLOYEE account with ZERO access (see lib/staff-grants.ts —
 * EMPLOYEE has no area until an explicit StaffGrant exists). The temp password
 * is returned to the caller exactly once; only its bcrypt hash is ever stored,
 * at the same cost factor (12) as every other password write in this codebase
 * (lib/actions.ts's register, lib/actions-account.ts's changePassword) so this
 * account is no weaker than one a customer created themselves.
 */
export async function createEmployee(
  email: string,
  name: string,
): Promise<{ ok: true; tempPassword: string } | { ok: false; error: string }> {
  const admin = await requireAdmin();

  const cleanEmail = normalizeEmail(email);
  const cleanName = String(name ?? "").trim().slice(0, 100);
  if (!cleanEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail)) {
    return { ok: false, error: "Enter a valid email address." };
  }
  if (!cleanName) return { ok: false, error: "Enter a name." };

  const existing = await db.user.findUnique({ where: { email: cleanEmail }, select: { id: true } });
  if (existing) return { ok: false, error: "An account with that email already exists." };

  // base64url so it's copy-pasteable with no shell/URL-escaping surprises.
  const tempPassword = randomBytes(9).toString("base64url");
  const employee = await db.user.create({
    data: {
      email: cleanEmail,
      name: cleanName,
      role: "EMPLOYEE",
      passwordHash: await bcrypt.hash(tempPassword, 12),
    },
  });

  await db.auditLog.create({
    data: { userId: admin.id, action: "staff.createEmployee", detail: `${employee.email} (${employee.id})` },
  });

  revalidatePath("/admin/staff");
  return { ok: true, tempPassword };
}

/**
 * Grant/revoke ONE area for ONE employee. This is the single write path for
 * StaffGrant — every area an EMPLOYEE ever reaches traces back to a row this
 * function wrote, which is what makes the audit log below a complete history
 * of who could do what and when.
 *
 * Deliberately refuses non-EMPLOYEE targets: hasAreaAccess() in
 * lib/staff-grants.ts only ever consults StaffGrant for role === "EMPLOYEE",
 * so a row on a SUPPORT/BILLING/ADMIN account would silently do nothing —
 * an error here is more honest than a checkbox that appears to save but never
 * has any effect.
 */
export async function setStaffGrant(
  userId: string,
  area: Area,
  granted: boolean,
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();

  if (!isGrantableArea(area)) return { error: "Not a grantable area." };

  const target = await db.user.findUnique({ where: { id: userId }, select: { role: true, email: true } });
  if (!target) return { error: "User not found." };
  if (target.role !== "EMPLOYEE") return { error: "Grants only apply to Role.EMPLOYEE accounts." };

  if (granted) {
    await db.staffGrant.upsert({
      where: { userId_area: { userId, area } },
      create: { userId, area, createdById: admin.id },
      update: {},
    });
  } else {
    await db.staffGrant.deleteMany({ where: { userId, area } });
  }

  await db.auditLog.create({
    data: { userId: admin.id, action: "staff.setGrant", detail: `${target.email}: ${area} → ${granted}` },
  });

  revalidatePath(`/admin/staff/${userId}`);
  return { ok: true };
}

/**
 * Add one CIDR to an employee's staff-portal IP allowlist. `normalizeCidr`
 * (lib/firewall-rules.ts) is the same gate the guest firewall uses — reused
 * rather than reimplemented so a "valid CIDR" can never mean two different
 * things in this codebase.
 */
export async function addStaffIp(
  userId: string,
  cidr: string,
  label?: string,
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();

  const target = await db.user.findUnique({ where: { id: userId }, select: { role: true, email: true } });
  if (!target) return { error: "User not found." };
  if (target.role !== "EMPLOYEE") return { error: "IP allowlists only apply to Role.EMPLOYEE accounts." };

  const normalized = normalizeCidr(cidr);
  if (!normalized) {
    return { error: "Enter a valid IPv4 address or CIDR range (e.g. 203.0.113.4 or 203.0.113.0/24)." };
  }

  const duplicate = await db.staffIpAllow.findFirst({ where: { userId, cidr: normalized }, select: { id: true } });
  if (duplicate) return { error: "That range is already on the list." };

  await db.staffIpAllow.create({
    data: { userId, cidr: normalized, label: label?.trim().slice(0, 80) || null },
  });
  await db.auditLog.create({
    data: { userId: admin.id, action: "staff.addIp", detail: `${target.email}: ${normalized}` },
  });

  revalidatePath(`/admin/staff/${userId}`);
  return { ok: true };
}

export async function removeStaffIp(userId: string, id: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();

  const row = await db.staffIpAllow.findUnique({ where: { id }, select: { userId: true, cidr: true } });
  if (!row || row.userId !== userId) return { error: "Not found." };

  await db.staffIpAllow.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "staff.removeIp", detail: `user=${userId}: ${row.cidr}` },
  });

  revalidatePath(`/admin/staff/${userId}`);
  return { ok: true };
}

