import type { Role } from "@prisma/client";

/**
 * Where a freshly authenticated user lands after login (or when an
 * already-signed-in visitor hits /login). A single exported helper so
 * lib/actions.ts's login action and app/login/page.tsx's redirect can never
 * drift apart on this decision as more roles get their own home.
 */
export function roleHome(role: Role): string {
  if (role === "ADMIN") return "/admin";
  if (role === "EMPLOYEE") return "/staff";
  return "/dashboard";
}

