import { redirect } from "next/navigation";
import type { Role, User } from "@prisma/client";
import { db } from "./db";
import { realUser } from "./auth";
import { canAccess, isStaff, type Area } from "./rbac";

/**
 * Per-employee (Role.EMPLOYEE) tool grants, layered ADDITIVELY on top of
 * lib/rbac.ts's role→area system — nothing in lib/rbac.ts changes behavior
 * for CUSTOMER/SUPPORT/BILLING/ADMIN. `canAccess`/`requireArea` there are
 * untouched; every one of their ~115 existing call sites is unaffected.
 *
 * EMPLOYEE is never listed in AREA_ROLES for any area (see lib/rbac.ts), so
 * an EMPLOYEE has ZERO access anywhere until a StaffGrant row exists for
 * them. This module is the only thing that ever reads StaffGrant, and it is
 * only ever consulted for the EMPLOYEE role — the fast path for every other
 * role is the existing, unchanged `canAccess` check with no DB hit.
 *
 * WHY A SEPARATE MODULE FROM lib/rbac.ts: keeps that file's existing,
 * heavily-relied-on exports byte-identical, so a diff against it proves this
 * feature couldn't have regressed anything already using it.
 *
 * LESSON APPLIED FROM lib/team-guard.ts's DELETION: that per-org permission
 * system was ripped out because it only ever filtered nav — no loader or
 * action actually checked it, so the "permission" was a promise the server
 * never kept. Every area opened to EMPLOYEE here is migrated at the ACTION
 * layer (see lib/actions-reddit-templates.ts, lib/actions-company-mail.ts,
 * lib/mail/imap.ts's resolveMailbox, lib/actions-support.ts's
 * requireTicketActor, lib/actions-chat.ts), not just its page.
 */

export async function hasAreaAccess(user: Pick<User, "id" | "role">, area: Area): Promise<boolean> {
  if (canAccess(user.role, area)) return true;
  if (user.role !== "EMPLOYEE") return false;
  const grant = await db.staffGrant.findUnique({
    where: { userId_area: { userId: user.id, area } },
    select: { id: true },
  });
  return !!grant;
}

export async function hasAnyAreaAccess(user: Pick<User, "id" | "role">, areas: Area[]): Promise<boolean> {
  for (const area of areas) {
    if (await hasAreaAccess(user, area)) return true;
  }
  return false;
}

/** Server-action guard. Throws UNAUTHORIZED/FORBIDDEN — never redirects. */
export async function requireGrant(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
  if (!(await hasAreaAccess(user, area))) throw new Error("FORBIDDEN");
  return user;
}

/** Server-action guard, OR-of-areas variant (e.g. company mail listing, reachable via either grant). */
export async function requireAnyGrant(areas: Area[]): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
  if (!(await hasAnyAreaAccess(user, areas))) throw new Error("FORBIDDEN");
  return user;
}

/**
 * Page guard — shape-compatible drop-in for lib/rbac.ts's `requireArea`, so
 * migrating a page file is a one-line swap. Redirects instead of throwing:
 * /login if signed out, /dashboard if not staff and not a granted EMPLOYEE,
 * /admin if staff but this specific area isn't reachable.
 */
export async function requireAreaOrGrant(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role) && user.role !== "EMPLOYEE") redirect("/dashboard");
  if (!(await hasAreaAccess(user, area))) {
    redirect(user.role === "EMPLOYEE" ? "/staff" : "/admin");
  }
  return user;
}

/** Every area an EMPLOYEE has been granted — drives the staff portal's dynamic nav and the admin grant checklist. */
export async function listGrantedAreas(userId: string): Promise<Area[]> {
  const rows = await db.staffGrant.findMany({ where: { userId }, select: { area: true } });
  return rows.map((r) => r.area as Area);
}

/**
 * The fixed list of areas an admin can grant an EMPLOYEE, plus display
 * metadata for the grant checklist (admin/staff/StaffGrantChecklist.tsx) and
 * the staff portal's dynamic nav. Adding a future grantable tool is a
 * one-line addition here — nothing else needs to change to surface it.
 */
export const GRANTABLE_AREAS: { area: Area; label: string; href: string; hint?: string }[] = [
  { area: "supportTickets", label: "Support tickets", href: "/staff/support" },
  { area: "liveChat", label: "Live chat", href: "/staff/chat" },
  { area: "redditTemplates", label: "Reddit templates", href: "/staff/reddit", hint: "Static content library — no live posting, no customer data." },
  { area: "companyInbox", label: "Company inbox", href: "/staff/inbox", hint: "Read/send as admin@, support@, etc. — never a customer's mail." },
  { area: "companyMailboxes", label: "Company mailboxes", href: "/staff/mailboxes", hint: "Create/reset company addresses — no customer billing or PII." },
  { area: "clientsBasic", label: "Clients (limited)", href: "/staff/clients", hint: "Name, email, signup date, ticket/server counts only — no financials, IPs, or audit trail." },
  { area: "tasks", label: "Tasks & projects", href: "/staff/tasks" },
];

